REPLACE INTO `portal_interview_company` (`id`, `name`, `slug`, `logo`, `description`, `industry`, `question_count`, `sort`, `status`, `create_by`, `create_time`, `update_by`, `update_time`, `remark`, `del_flag`) VALUES (1,'阿里巴巴',NULL,'https://tmpic.tmkoo.com/ce24431ca362f8d9967541ee3bb13223?v=2022','阿里巴巴集团控股有限公司是一家旨在让天下没有难做的生意的互联网公司。其业务涵盖电商（淘宝、天猫）、云计算（阿里云）、数字媒体及娱乐、创新业务等。技术栈以 Java 为主，拥有强大的中间件团队，是 Java 后端工程师的“黄埔军校”，对高并发、分布式架构有极高要求。','互联网 / 电子商务',0,1,'active','','2026-09-29 11:07:46','','2026-09-29 11:30:47',NULL,'0'),(2,'字节跳动',NULL,'https://sf1-cdn-tos.toutiaostatic.com/obj/ttfe/pgc/image/byte_logo.png','字节跳动是全球领先的互联网科技公司，旗下产品包括抖音、今日头条、TikTok 等。公司以“Always Day 1”为文化核心，技术氛围浓厚，推崇 Go 和 Java 混合架构。面试风格偏向算法与基础原理（如 LeetCode 原题），对候选人的逻辑思维和学习能力考察严格。','互联网 / 人工智能 / 短视频',0,2,'','','2026-09-29 11:17:05','','2026-09-29 11:17:05',NULL,'0'),(3,'字节跳动',NULL,'https://pics4.baidu.com/feed/34fae6cd7b899e51ae15bd21a5b8723ec8950d1d.jpeg@f_auto?token=991fd02063542cd99daf0b89a309f5b7','字节跳动是全球领先的互联网科技公司，旗下产品包括抖音、今日头条、TikTok 等。公司以“Always Day 1”为文化核心，技术氛围浓厚，推崇 Go 和 Java 混合架构。面试风格偏向算法与基础原理（如 LeetCode 原题），对候选人的逻辑思维和学习能力考察严格。','互联网 / 人工智能 / 短视频',0,2,'active','','2026-09-29 11:32:21','','2026-09-29 11:33:09',NULL,'0');


-- ----------------------------------------------------------------------------
