REPLACE INTO `portal_job_template` (`id`, `name`, `category`, `position_code`, `code`, `industry`, `level`, `required_skills`, `hot_companies`, `sort`, `description`, `jd_text`, `keywords`, `difficulty`, `question_count`, `weights`, `status`, `create_by`, `create_time`, `update_by`, `update_time`, `remark`, `del_flag`) VALUES (1,'初级 Java 开发工程师','技术','0111','java_backend','互联网','junior','[\"Java\",\"Spring\",\"SpringBoot\",\"MyBatis\",\"MySQL\",\"Redis\",\"MQ\",\"JVM\",\"并发编程\",\"分布式\",\"微服务\",\"设计模式\"]','[\"阿里\",\"腾讯\",\"字节跳动\",\"美团\",\"京东\",\"百度\",\"拼多多\",\"网易\",\"滴滴\",\"快手\"]',1,'java后端 测试','初级 Java 开发工程师（0-2 年经验）\n薪资范围：8K - 15K · 13薪\n工作地点：深圳市南山区\n学历要求：本科及以上，计算机相关专业\n岗位职责：\n参与公司核心业务系统的功能开发与维护\n根据需求文档完成模块编码、单元测试及问题修复\n配合前端完成接口联调，确保功能正常交付\n编写技术文档，参与代码评审\n任职要求：\n熟练掌握 Java 基础，理解面向对象编程思想，熟悉集合、多线程、IO 等核心 API\n了解 Spring / Spring Boot 框架，能独立完成 CRUD 功能开发\n熟悉 MySQL 数据库，能编写基本的 SQL 语句，了解索引概念\n了解 Redis 基本使用，知道缓存的常见应用场景\n了解 HTTP 协议，能使用 Postman / Swagger 进行接口调试\n具备良好的学习能力和沟通协作能力，对技术有热情\n加分项：\n有个人技术博客或 GitHub 开源项目\n了解 Docker 基本操作\n有实习或校招项目经验','Java,Spring,SpringBoot,MyBatis,MySQL,Redis,并发编程','easy',10,'{\"job\":40,\"resume\":30,\"weak\":20,\"random\":10}','active','','2026-09-29 10:22:49','','2026-09-29 13:19:19',NULL,'0'),(2,'中级 Java 开发工程师（2-5 年经验）','技术','0222','java_backend_mid','互联网','mid','[\"Java\",\"Spring\",\"SpringBoot\",\"MyBatis\",\"MySQL\",\"Redis\",\"MQ\",\"JVM\",\"并发编程\",\"分布式\",\"微服务\",\"设计模式\"]','[\"阿里\",\"腾讯\",\"字节跳动\",\"美团\",\"京东\",\"百度\",\"拼多多\",\"网易\",\"滴滴\",\"快手\"]',2,'中级 Java 开发工程师（（2-5 年经验）','中级 Java 开发工程师（2-5 年经验）\n薪资范围：18K - 30K · 14-16薪\n工作地点：深圳市南山区\n\n岗位职责：\n1. 独立负责业务模块的设计、开发与上线，对交付质量负责\n2. 参与系统性能优化、慢查询治理与线上故障定位\n3. 参与技术方案评审，输出设计文档\n\n任职要求：\n1. 本科及以上学历，2-5 年 Java 后端开发经验\n2. 熟悉 JVM 内存模型与 GC 调优，具备并发编程实战经验\n3. 熟悉 MySQL 索引优化与事务隔离级别；熟悉 Redis 缓存设计与穿透/雪崩防护\n4. 熟悉消息队列（Kafka/RocketMQ）使用场景与可靠投递\n5. 了解分布式与微服务（Spring Cloud/Dubbo）相关组件','Java,JVM,并发编程,MySQL,Redis,消息队列,分布式,微服务','medium',8,'{\"job\":40,\"resume\":30,\"weak\":20,\"random\":10}','active','','2026-09-29 10:24:33','','2026-09-29 13:19:53',NULL,'0'),(3,'高级 / 资深 Java 开发工程师（5 年以上经验）','技术','0333','java_backend_senior','互联网','senior','[\"Java\",\"Spring\",\"SpringBoot\",\"MyBatis\",\"MySQL\",\"Redis\",\"MQ\",\"JVM\",\"并发编程\",\"分布式\",\"微服务\",\"设计模式\"]','[\"阿里\",\"腾讯\",\"字节跳动\",\"美团\",\"京东\",\"百度\",\"拼多多\",\"网易\",\"滴滴\",\"快手\"]',3,'高级 / 资深 Java 开发工程师（5 年以上经验）','薪资范围：35K - 60K · 15-18薪 + 期权\n工作地点：深圳市南山区\n学历要求：本科及以上，计算机相关专业\n岗位职责：\n负责核心系统的架构设计与技术选型，主导重大技术难题攻关\n规划系统演进方向，推动技术架构升级，保障系统高可用、高并发、高扩展\n主导代码评审与技术规范制定，提升团队整体技术水平\n跨部门技术协作，与产品、前端、测试、运维等团队高效配合\n跟踪行业技术趋势，引入新技术提升研发效率和系统质量\n任职要求：\n精通 Java 技术栈，深入理解 JVM 原理，有丰富的线上性能调优和故障排查经验\n精通 Spring 全家桶，深入理解 Spring 核心原理（IOC / AOP / 事务机制等），阅读过核心源码\n精通 MySQL 数据库设计与优化，有分库分表、读写分离实战经验\n精通 Redis，深入理解其数据结构、持久化机制、集群方案，有大规模缓存架构设计经验\n精通至少一种消息队列，有海量消息场景下的架构设计与调优经验\n深入理解分布式系统理论（CAP / BASE），有分布式事务、服务治理、链路追踪等落地经验\n熟悉 Elasticsearch 集群架构与调优，有亿级数据搜索场景经验\n熟悉云原生技术栈（Docker / K8s / Service Mesh），有容器化部署和运维经验\n具备优秀的系统设计能力，能独立输出高质量的技术方案文档\n具备技术领导力，能带领 5 人以上技术团队完成复杂项目交付\n加分项：\n有从 0 到 1 搭建中台或核心系统的经验\n有开源项目贡献或核心技术专利\n有大型互联网公司（BAT / TMD 等）工作背景\n在 QCon / ArchSummit 等技术大会做过分享','Java,架构设计,高并发,JVM调优,分布式,微服务,分库分表,稳定性','hard',5,'{\"job\":40,\"resume\":30,\"weak\":20,\"random\":10}','active','','2026-09-29 10:26:14','','2026-09-29 13:19:19',NULL,'0'),(5,'前端工程师','技术',NULL,'frontend','互联网','mid','[\"JavaScript\",\"TypeScript\",\"Vue\",\"React\",\"HTML\",\"CSS\",\"Node.js\",\"Webpack\",\"Vite\",\"性能优化\",\"浏览器原理\",\"HTTP\"]','[\"阿里\",\"腾讯\",\"字节跳动\",\"美团\",\"京东\",\"百度\",\"网易\",\"小米\",\"Shopee\",\"滴滴\"]',4,'前端工程师岗位，重点考察 JS/TS 基础、Vue/React 框架、工程化、浏览器原理、性能优化、HTTP 与网络','前端工程师\n薪资范围：18K - 32K · 14-16薪\n工作地点：深圳市南山区\n\n岗位职责：\n1. 负责公司 Web 端产品的开发与迭代，保障交互体验与性能\n2. 参与前端工程化建设（构建、组件库、规范与自动化）\n3. 与后端协作完成接口联调与线上问题排查\n\n任职要求：\n1. 本科及以上学历，2 年以上前端开发经验\n2. 扎实的 JavaScript / TypeScript 基础，熟悉 ES6+ 与异步编程\n3. 熟练掌握 Vue 或 React 其一，理解其响应式与渲染机制\n4. 熟悉 Webpack / Vite 构建原理与常用优化手段\n5. 熟悉浏览器渲染原理、HTTP 缓存与前端性能优化（LCP/CLS 等指标）','JavaScript,TypeScript,Vue,React,工程化,浏览器原理,性能优化,HTTP','medium',8,'{\"job\":40,\"resume\":30,\"weak\":20,\"random\":10}','active','admin','2026-09-29 13:18:54','','2026-09-29 13:19:53','原 portal_interview_position 迁入','0'),(6,'算法工程师','技术',NULL,'algorithm','互联网','mid','[\"算法\",\"数据结构\",\"动态规划\",\"图论\",\"字符串\",\"数组\",\"链表\",\"树\",\"递归\",\"排序\",\"机器学习\",\"深度学习\",\"数学\"]','[\"阿里\",\"腾讯\",\"字节跳动\",\"百度\",\"美团\",\"快手\",\"小红书\",\"华为\",\"商汤\",\"旷视\"]',5,'算法工程师岗位，重点考察数据结构与算法、动态规划、图论、字符串算法、机器学习与深度学习基础','算法工程师\n薪资范围：25K - 45K · 15-16薪\n工作地点：深圳市南山区\n\n岗位职责：\n1. 负责推荐/搜索/NLP 等方向算法模型的设计、训练与上线\n2. 结合业务指标持续迭代模型效果，完成 A/B 实验与归因分析\n3. 参与特征工程与数据链路建设\n\n任职要求：\n1. 硕士及以上学历，计算机/数学/统计相关专业\n2. 扎实的数据结构与算法基础，熟悉动态规划、图论与字符串算法\n3. 熟悉机器学习常用模型与评估指标，了解深度学习基本原理\n4. 熟练使用 Python 及主流框架（PyTorch/TensorFlow）\n5. 有推荐、搜索或 NLP 相关项目经验者优先','算法,数据结构,动态规划,图论,机器学习,深度学习,数学','medium',8,'{\"job\":40,\"resume\":30,\"weak\":20,\"random\":10}','active','admin','2026-09-29 13:18:54','','2026-09-29 13:19:53','原 portal_interview_position 迁入','0');


